// A boss fight joins the vault once that boss has been beaten (recorded since v0.55; older wins count through the boss's own unlock).
function bossBeaten(profile,bossId){if((profile.bossesBeaten||[]).includes(bossId))return true;const b=bossById(bossId);return !!(b?.unlockId&&!b.unlockPool&&(profile.shared||[]).includes(b.unlockId));}
function gameUnlocked(game,profile){if(game.bossId)return bossBeaten(profile,game.bossId);if(game.secret)return (profile.modes||[]).includes('coop');return STARTER_FAMILIES.has(game.family)||!game.gameUnlockAt||(profile.minigames||0)>=game.gameUnlockAt||(profile.games||[]).includes(game.id);}
